SINA_SMART["toxico-experimental"] = {"lecture":"toxico-experimental","title":"Experimental (preclinical) toxicology","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"toxico-experimental:e0","text":"Thalidomide: untested teratogen, withdrawn 26 November 1961; now used in myeloma and leprosy.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"toxico-experimental:e1","text":"LD₅₀: dose killing 50% of animals; lower LD₅₀ = more toxic.","topic":"Single-dose (acute) studies","sec":1,"importance":"core","highYield":"untested"},{"id":"toxico-experimental:e2","text":"LC₅₀ is used for inhalation (mg/L or ppm).","topic":"Single-dose (acute) studies","sec":1,"importance":"core","highYield":"untested"},{"id":"toxico-experimental:e3","text":"Acute studies: rodents, ~5/sex/dose, 14-day observation.","topic":"Single-dose (acute) studies","sec":1,"importance":"core","highYield":"foundational"},{"id":"toxico-experimental:e4","text":"3Rs: Replace, Reduce, Refine.","topic":"Single-dose (acute) studies","sec":1,"importance":"core","highYield":"untested"},{"id":"toxico-experimental:e11","text":"Carcinogenicity studies last 18-24 months in rodents.","topic":"Repeated-dose studies","sec":2,"importance":"core","highYield":"historically-high-yield"},{"id":"toxico-experimental:e6","text":"Repeated dose: 28 days, 90 days, ≥ 6 months; key output NOAEL.","topic":"Repeated-dose studies","sec":2,"importance":"core","highYield":"untested"},{"id":"toxico-experimental:e5","text":"Limit test at 2,000 mg/kg replaces full LD₅₀ tests.","topic":"Genotoxicity","sec":3,"importance":"core","highYield":"untested"},{"id":"toxico-experimental:e7","text":"Genotoxicity battery: Ames, mammalian cell assay, in vivo micronucleus.","topic":"Genotoxicity","sec":3,"importance":"core","highYield":"untested"},{"id":"toxico-experimental:e8","text":"Ames: histidine-dependent Salmonella, with and without S9.","topic":"Genotoxicity","sec":3,"importance":"core","highYield":"untested"},{"id":"toxico-experimental:e9","text":"Micronucleus detects clastogens and aneugens.","topic":"Genotoxicity","sec":3,"importance":"core","highYield":"untested"},{"id":"toxico-experimental:e10","text":"IARC group 1: tobacco, asbestos, aflatoxins.","topic":"Carcinogenicity and reproductive toxicity","sec":4,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"1x9q4ac":"a","1txybw6":"a","1oqecak":"a","2ttzln":"a","1jln1l0":"a","1vge0wp":"a","1pjgqz0":"a","100yplk":"a","fkn76":"a","zwxyu3":"a","rllz49":"a","1sq2cw7":"a","5v1n89":"a","e1nbn2":"a","9a2aei":"a","17zryyd":"x","jdhn04":"x"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":2},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"toxico-experimental:e0":{"s":0,"u":["Thalidomide: untested teratogen, withdrawn 26 November 1961; now used in myeloma and leprosy.","The thalidomide disaster shows why: marketed in the 1950s (Contergan, Chemie Grünenthal) as a sedative and used for morning sickness without teratogenicity testing, it caused congenital malformations and was withdrawn on 26 November 1961 .","Its antiangiogenic action (VEGF inhibition) is now used in myeloma, leprosy, severe aphthous stomatitis and cutaneous lupus."],"dp":[{"h":"Why thalidomide changed drug regulation","t":"Thalidomide looked safe in the tests of its time, which did not examine pregnant animals. Thousands of children were born with limb defects before the link was made. The disaster led regulators to require embryo-fetal development studies before approval, which is exactly the reproductive toxicity testing this lecture describes. Source: the lecture's thalidomide slides."}]},"toxico-experimental:e1":{"s":1,"u":["LD₅₀: dose killing 50% of animals; lower LD₅₀ = more toxic.","LD₅₀ in mg/kg body weight; LC₅₀ in mg/L (or ppm) for inhalation; the lower the value, the more toxic (Trevan's median lethal dose).","Evaluate effects of one exposure: approximate LD₅₀ (dose killing 50% of animals) or MTD, target organs, clinical signs, onset, duration and reversibility."],"dp":[]},"toxico-experimental:e2":{"s":1,"u":["LC₅₀ is used for inhalation (mg/L or ppm).","LD₅₀ in mg/kg body weight; LC₅₀ in mg/L (or ppm) for inhalation; the lower the value, the more toxic (Trevan's median lethal dose)."],"dp":[]},"toxico-experimental:e3":{"s":1,"u":["Acute studies: rodents, ~5/sex/dose, 14-day observation.","Rodents, both sexes, young healthy adults, about 5 per sex per dose ; route as in humans (oral most common); controls receive vehicle; observation 14 days ; necropsy of all animals."],"dp":[]},"toxico-experimental:e4":{"s":1,"u":["3Rs: Replace, Reduce, Refine.","Ethics: the 3Rs (Replace, Reduce, Refine)."],"dp":[]},"toxico-experimental:e11":{"s":2,"u":["Carcinogenicity studies last 18-24 months in rodents.","Rodents, sometimes dogs or monkeys for longer studies; 3 dose levels + control (low: no toxicity; mid: mild effects; high: clear but non-lethal toxicity)."],"dp":[]},"toxico-experimental:e6":{"s":2,"u":["Repeated dose: 28 days, 90 days, ≥ 6 months; key output NOAEL.","Durations: subacute 28 days, subchronic 90 days, chronic 6 months or more (up to 2 years) ."],"dp":[]},"toxico-experimental:e5":{"s":3,"u":["Limit test at 2,000 mg/kg replaces full LD₅₀ tests.","Standard battery: Ames test , an in vitro mammalian cell assay, and an in vivo micronucleus test."],"dp":[{"h":"Why the Ames test uses liver extract","t":"Many carcinogens, such as benzopyrene, are harmless until liver enzymes convert them into reactive metabolites. Bacteria lack these enzymes, so a test without them would miss such compounds. Adding S9, the liver microsome fraction, lets the test catch substances that become mutagenic only after metabolism. Source: the lecture's Ames test slides."}]},"toxico-experimental:e7":{"s":3,"u":["Genotoxicity battery: Ames, mammalian cell assay, in vivo micronucleus.","Standard battery: Ames test , an in vitro mammalian cell assay, and an in vivo micronucleus test."],"dp":[]},"toxico-experimental:e8":{"s":3,"u":["Ames: histidine-dependent Salmonella, with and without S9.","Ames test (OECD 471): histidine-dependent Salmonella typhimurium strains (TA98, TA100, TA1535) on histidine-free medium; a mutagen causes reverse mutations and revertant colonies grow; run with and without S9 liver extract to detect mutagens needing metabolic activation; fast, cheap, sensitive."],"dp":[]},"toxico-experimental:e9":{"s":3,"u":["Micronucleus detects clastogens and aneugens."],"dp":[]},"toxico-experimental:e10":{"s":4,"u":["IARC group 1: tobacco, asbestos, aflatoxins.","IARC groups: 1 carcinogenic (tobacco smoke, asbestos, aflatoxins), 2A probably (glyphosate, red meat, frying emissions), 2B possibly (mobile phone radiation, aloe vera extract), 3 not classifiable (caffeine, tea), 4 probably not (caprolactam, the only one)."],"dp":[]}},"meta":{"1x9q4ac":{"a":"relationship","vg":"toxico-experimental:e0/relationship/1"},"1txybw6":{"a":"recall","vg":"toxico-experimental:e0/recall/1"},"1oqecak":{"a":"recall","vg":"toxico-experimental:e1/recall/1"},"2ttzln":{"a":"recall","vg":"toxico-experimental:e1/recall/2"},"1jln1l0":{"a":"recall","vg":"toxico-experimental:e2/recall/1"},"1vge0wp":{"a":"recall","vg":"toxico-experimental:e6/recall/1"},"1pjgqz0":{"a":"recall","vg":"toxico-experimental:e4/recall/1"},"100yplk":{"a":"recall","vg":"toxico-experimental:e6/recall/1"},"fkn76":{"a":"recall","vg":"toxico-experimental:e6/recall/2"},"zwxyu3":{"a":"recall","vg":"toxico-experimental:e8/recall/1"},"rllz49":{"a":"relationship","vg":"toxico-experimental:e8/relationship/1"},"1sq2cw7":{"a":"recall","vg":"toxico-experimental:e9/recall/1"},"5v1n89":{"a":"recall","vg":"toxico-experimental:e5/recall/1"},"e1nbn2":{"a":"recall","vg":"toxico-experimental:e10/recall/1"},"9a2aei":{"a":"recall","vg":"toxico-experimental:e11/recall/1"}},"explRev":"c68819f3dfad"};
